//! tu::grtcaptain against the C TU compiled natively with shipping contraction (state oracle:
//! gen/turef/tu_grtcaptain_ref.c, data tests/data/tu_grtcaptain.txt; regenerate with
//! `python rust/melee_world/gen/turef/tu_shard585.py grtcaptain`). Generated by gen_target_stage.py.
#![allow(static_mut_refs, non_snake_case, unused)]
mod common;
use common::gr::*;
use common::*;
use melee_types::*;
use melee_world::tu::grtcaptain as t;
use melee_world::tu_ext as ext;

include!("stubs/grtcaptain.rs");

unsafe fn state() {
    out(&format!("rs {}\n", ORS));
    out(&format!("si {} {}\n", ext::stage_info.unk8C.b4(), ext::stage_info.unk8C.b5()));
    dump_arena();
    state_end();
}

macro_rules! fnr {
    ($($p:path),* $(,)?) => { $( fnreg(stringify!($p).rsplit("::").next().unwrap(), $p as usize); )* };
}

#[test]
fn matches_c() {
    unsafe {
        reset_all();
        gen_stubs::install();
        install_custom();
        size_t::<Ground>("Ground");
        size_t::<HSD_GObj>("HSD_GObj");
        size_t::<HSD_JObj>("HSD_JObj");
        size_t::<StageCallbacks>("StageCallbacks");
        size_t::<StageData>("StageData");
        reg("cb", t::grTCa_StageCallbacks.as_ptr(), core::mem::size_of_val(&t::grTCa_StageCallbacks));
        reg("sd", &t::grTCa_StageData, core::mem::size_of::<StageData>());
        reg("dat", t::grTCa_StageData.data1, 16);
        fnr!(t::grTCaptain_OnDemoInit, t::grTCaptain_OnInit, t::grTCaptain_OnLoad, t::grTCaptain_OnStart, t::grTCaptain_8021FCFC, t::grTCaptain_8021FD04, t::grTCaptain_OnTouchLine, t::grTCaptain_OnCheckShadowRender, t::stageGObj0_OnInit, t::grTCaptain_8021FE18, t::grTCaptain_8021FE20, t::grTCaptain_8021FE24, t::stageGObj1_OnInit, t::grTCaptain_8021FF08, t::stageGObj1_GObjProc, t::grTCaptain_8021FF30, t::stageGObj2_OnInit, t::grTCaptain_8021FE78, t::stageGObj2_GObjProc, t::grTCaptain_8021FEB4);
        fnreg("grDisplay_801C5DB0", ext::grDisplay_801C5DB0 as usize);
        dump_t("cb", &t::grTCa_StageCallbacks);
        dump_t("sd", &t::grTCa_StageData);
        state_end();

        for c in 0..60usize {
            case(c);
            rseed(100 + c as u32);
            gr_reset();
            ext::stage_info.unk8C.set_b4((rnd() & 1) as u8);
            ext::stage_info.unk8C.set_b5((rnd() & 1) as u8);
            out("r");
            trp(t::grTCaptain_8021FD04((c % 3) as i32) as *const u8);
            out("\n");
            state();
        }
        for c in 0..20usize {
            case(1000 + c);
            rseed(2000 + c as u32);
            gr_reset();
            t::grTCaptain_OnInit();
            state();
            t::grTCaptain_OnStart();
            t::grTCaptain_OnLoad();
            t::grTCaptain_OnDemoInit(rnd() as i32);
            state();
        }
        for c in 0..12usize {
            case(2000 + c);
            rseed(3000 + c as u32);
            gr_reset();
            let g = mkgobj();
            t::stageGObj0_OnInit(g);
            state();
            out(&format!("r {}\n", t::grTCaptain_8021FE18(g)));
            t::grTCaptain_8021FE20(g);
            t::grTCaptain_8021FE24(g);
            state();
            t::stageGObj1_OnInit(g);
            state();
            out(&format!("r {}\n", t::grTCaptain_8021FF08(g)));
            t::stageGObj1_GObjProc(g);
            t::grTCaptain_8021FF30(g);
            state();
            t::stageGObj2_OnInit(g);
            state();
            out(&format!("r {}\n", t::grTCaptain_8021FE78(g)));
            t::stageGObj2_GObjProc(g);
            t::grTCaptain_8021FEB4(g);
            state();
            out(&format!("r {}\n", t::grTCaptain_8021FCFC()));
            out("r");
            trp(t::grTCaptain_OnTouchLine(rnd() as i32) as *const u8);
            out("\n");
            let mut v = Vec3 { x: rf(), y: rf(), z: rf() };
            let a1 = rnd() as i32;
            let j = mkjobj();
            out(&format!("r {}\n", t::grTCaptain_OnCheckShadowRender(&mut v, a1, j)));
            state();
        }
    }
    check("tu_grtcaptain");
}
